/**
 * 势 — historical inertia, deliberately soft.
 *
 * The mode is "扮演": the player may leave the historical path. That means this
 * module must NEVER veto a choice, never silently rewrite one, and never say
 * "history says no". What it does instead is price the deviation.
 *
 * The mechanism is a single scalar, `drift`, plus a derived `pressure`:
 *
 *   drift    accumulates every time the player acts against what their actual
 *            resources could support (declaring yourself a warlord with 300 men,
 *            refusing a benefactor who is feeding you, keeping a city you cannot
 *            hold). It decays slowly when the player acts within their means.
 *   pressure is what the world does about it — harder checks, colder NPCs,
 *            more opportunistic neighbours. It is applied as a MODIFIER, never
 *            as a refusal.
 *
 * Two design consequences worth stating out loud:
 *
 *   1. A player who plays far beyond their means gets a world that pushes back
 *      hard — not a cutscene that undoes the choice. This is the difference
 *      between a simulation and a rail.
 *   2. `pressure` is bounded. A player who insists on an absurd path reaches a
 *      permanently hostile world but is never locked out. The failure mode is
 *      "everything is hard", which is a playable state, not a dead end.
 *
 * The historical node table lives in data/acts.json; this file only knows how
 * to read it and how to price a departure from it.
 */

/** Drift added when the player takes a non-historical branch at a key node. */
export const DRIFT_PER_DEVIATION = 10

/** Drift added per point of resource shortfall against the branch's demand. */
export const DRIFT_PER_SHORTFALL = 0.5

/** Drift removed per turn spent acting within means. */
export const DRIFT_DECAY_PER_TURN = 2

/** Hard ceiling: past this the world is permanently hostile but still playable. */
export const DRIFT_MAX = 100

/** Pressure is the drift scaled down; it is a modifier, not a gate. */
export const PRESSURE_SCALE = 0.35

/** Cap on the penalty pressure may add to a single check. */
export const PRESSURE_CAP = 30

/**
 * Read the drift value from a save, tolerating old saves that lack it.
 */
export function readDrift(state) {
  const raw = state?.drift
  return Number.isFinite(raw) ? Math.min(DRIFT_MAX, Math.max(0, raw)) : 0
}

/**
 * Compute the pressure the world applies right now.
 *
 * Returned as a negative modifier value (so it can be pushed straight into
 * `check().modifiers`) plus the raw number for display. The engine clamps it,
 * because an uncapped penalty would effectively become the veto this module
 * exists to avoid.
 */
export function pressureOf(drift) {
  const value = Math.min(PRESSURE_CAP, Math.round(readDrift({ drift }) * PRESSURE_SCALE))
  return {
    value: -value,
    raw: value,
    reason: value === 0 ? '' : `天下侧目（势 ${value}）`
  }
}

/**
 * Does this branch depart from the recorded history?
 *
 * `historical: true` marks the branch the sources record. Everything else is a
 * departure. A node with no branch marked historical is treated as a free
 * choice — some moments genuinely had no canonical answer worth enforcing.
 */
export function isDeparture(node, branch) {
  if (node?.freeChoice === true) {
    return false
  }
  return branch?.historical !== true
}

/**
 * Price one choice.
 *
 * @param {object} input
 * @param {object} input.node      the act node
 * @param {object} input.branch    the branch the player picked
 * @param {object} input.state     current save (for drift + resources)
 * @param {object} input.resources { troops, gold, grain, fame, trust, talent }
 * @returns {{ drift, pressure, departure, shortfall, reasons: string[] }}
 */
export function priceChoice(input) {
  const node = input.node ?? {}
  const branch = input.branch ?? {}
  const state = input.state ?? {}
  const resources = input.resources ?? {}
  const reasons = []

  let drift = readDrift(state)
  const departure = isDeparture(node, branch)

  if (departure) {
    drift += DRIFT_PER_DEVIATION
    reasons.push('偏离史载')
  }

  // Resource shortfall: how far is the player's actual position from what this
  // branch assumes? Declaring a state with no army is the canonical example.
  const demand = branch.demand ?? {}
  let shortfall = 0
  for (const key of ['troops', 'gold', 'grain']) {
    const need = Number(demand[key])
    if (!Number.isFinite(need) || need <= 0) continue
    const have = Number(resources[key])
    const actual = Number.isFinite(have) ? have : 0
    if (actual < need) {
      // Normalise so a 10% shortfall and a 90% shortfall are comparable rather
      // than letting a big absolute number dominate every other term.
      shortfall += (need - actual) / need
    }
  }
  if (shortfall > 0) {
    drift += Math.round(shortfall * DRIFT_PER_SHORTFALL * 10) / 10
    reasons.push(`实力不足（缺口 ${shortfall.toFixed(2)}）`)
  }

  drift = Math.min(DRIFT_MAX, Math.max(0, drift))

  return {
    drift,
    pressure: pressureOf(drift),
    departure,
    shortfall,
    reasons
  }
}

/**
 * One turn of drift decay.
 *
 * Called by the clock when a period passes with no departure. Decay is slow on
 * purpose: a reputation for overreach should not wash out in a month.
 */
export function decay(state) {
  const drift = Math.max(0, readDrift(state) - DRIFT_DECAY_PER_TURN)
  return { drift }
}

/**
 * Describe the current drift in the register a person would use, not as a
 * number. The model may quote this verbatim; it may not invent a different
 * reading of the world's mood.
 */
export function describe(drift) {
  const value = readDrift({ drift })
  if (value === 0) return '天下未觉'
  if (value < 15) return '略有风闻'
  if (value < 35) return '人多侧目'
  if (value < 60) return '四方疑之'
  if (value < 85) return '天下共疑'
  return '举世皆敌'
}
